 private static void tryAddDecision(Set<Class<?>> out,ClassData d,ClassLoader l){try{addDecision(out,d.getInstance(l));}catch(Throwable t){XposedBridge.log(TAG+": optional enum relation skipped: "+d.getName());}}
 private static void addDecision(Set<Class<?>> out,Class<?> c){if(!c.isEnum())return;Set<String> n=new HashSet<>();for(Object e:c.getEnumConstants())n.add(((Enum<?>)e).name());if(n.containsAll(Arrays.asList("ALLOW_ONCE","ALLOW_APP_FOR_TASK","ALLOW_ALL_FOR_TASK","ALLOW_VISUAL_FOR_TASK","DENY","STOP","UNAVAILABLE")))out.add(c);}
 private static void collectLinkedEnums(MethodData gate,Set<Class<?>> out,ClassLoader l)throws Exception{for(MethodData call:gate.getInvokes())if("ordinal".equals(call.getMethodName())||"name".equals(call.getMethodName()))tryAddDecision(out,call.getDeclaredClass(),l);for(org.luckypray.dexkit.result.UsingFieldData use:gate.getUsingFields()){org.luckypray.dexkit.result.FieldData f=use.getField();tryAddDecision(out,f.getType(),l);if(!"int[]".equals(f.getType().getName()))continue;for(MethodData init:f.getDeclaredClass().getMethods())if(init.isStaticInitializer())for(org.luckypray.dexkit.result.UsingFieldData mapped:init.getUsingFields())tryAddDecision(out,mapped.getField().getType(),l);}}
